:root {
  --bg: #2b2b3c;
  --card: #3c3c54;
  --accent: #ffcc00;
  --text: #f0f0f0;
  --danger: #ff5e5e;
  --border: #5a5a7a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
  image-rendering: pixelated;
}

.card {
  background: var(--card);
  border: 4px solid var(--border);
  border-radius: 0;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.5);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 16px;
  text-align: center;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 #000;
}

.stats {
  display: flex;
  justify-content: space-between;
  margin-bottom: 16px;
  font-size: 1rem;
  padding: 8px 12px;
  background: var(--bg);
  border: 2px solid var(--border);
}

.stats strong {
  color: var(--accent);
  font-size: 1.2rem;
}

.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}

input[type="text"] {
  flex: 1;
  padding: 10px 12px;
  font-size: 1rem;
  background: var(--bg);
  border: 2px solid var(--border);
  color: var(--text);
  outline: none;
  border-radius: 0;
}

input[type="text"]:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}

button {
  padding: 10px 16px;
  font-size: 1rem;
  font-weight: bold;
  background: var(--accent);
  color: #000;
  border: 2px solid #000;
  border-radius: 0;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
  box-shadow: 3px 3px 0 #000;
  transition: transform 0.05s, box-shadow 0.05s;
}

button:hover {
  background: #ffe066;
}

button:active {
  transform: translate(3px, 3px);
  box-shadow: none;
}

button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.todo-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.todo-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  background: var(--bg);
  border: 2px solid var(--border);
}

.todo-item input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: var(--accent);
  cursor: pointer;
  flex-shrink: 0;
}

.todo-text {
  flex: 1;
  font-size: 1rem;
  word-break: break-word;
}

.todo-item input[type="checkbox"]:checked + .todo-text {
  text-decoration: line-through;
  opacity: 0.6;
}

.delete-btn {
  padding: 6px 10px;
  font-size: 0.9rem;
  background: var(--danger);
  color: #fff;
  border: 2px solid #000;
  box-shadow: 2px 2px 0 #000;
}

.delete-btn:hover {
  background: #ff7b7b;
}

.delete-btn:active {
  transform: translate(2px, 2px);
  box-shadow: none;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .card { padding: 16px; }
  h1 { font-size: 1.2rem; }
  .input-row { flex-direction: column; }
  button { width: 100%; }
}

let nextId = 1;
const tasks = new Map();

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');
const list = document.getElementById('todo-list');

function updateCounts() {
  totalEl.textContent = tasks.size;
  let incomplete = 0;
  tasks.forEach(t => { if (!t.done) incomplete++; });
  remainingEl.textContent = incomplete;
}

function createTaskElement(id, text) {
  const li = document.createElement('li');
  li.className = 'todo-item';
  li.dataset.id = id;

  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.id = `todo-check-${id}`;
  checkbox.setAttribute('aria-label', `Mark task ${id} as complete`);

  const span = document.createElement('span');
  span.className = 'todo-text';
  span.id = `todo-text-${id}`;
  span.textContent = text;

  const delBtn = document.createElement('button');
  delBtn.type = 'button';
  delBtn.id = `todo-delete-${id}`;
  delBtn.className = 'delete-btn';
  delBtn.textContent = '✕';
  delBtn.setAttribute('aria-label', `Delete task ${id}`);

  checkbox.addEventListener('change', () => {
    const task = tasks.get(id);
    if (task) {
      task.done = checkbox.checked;
      updateCounts();
    }
  });

  delBtn.addEventListener('click', () => {
    tasks.delete(id);
    li.remove();
    updateCounts();
  });

  li.appendChild(checkbox);
  li.appendChild(span);
  li.appendChild(delBtn);
  return li;
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;
  const id = nextId++;
  tasks.set(id, { text, done: false });
  list.appendChild(createTaskElement(id, text));
  input.value = '';
  input.focus();
  updateCounts();
}

addBtn.addEventListener('click', addTask);
input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') addTask();
});

updateCounts();
